import unittest
from email_validation import valid_email
class Tests(unittest.TestCase):
    def test_good(self):
        self.assertTrue(valid_email("a@b"))
    def test_invalid(self):
        for value in ("@b", "a@", "a@@b", "a b@c", "no-at"):
            self.assertFalse(valid_email(value))
